// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function testFuzz_property(uint256 tokenBal, uint256 transferAmount) public {
        // Deploy a foreign token helper that succeeds at balanceOf/transfer and records the call.
        SuccessfulForeignToken ft = new SuccessfulForeignToken();

        // The contract c is the owner because it deploys itself in setup. We'll use the
        // test contract as the current owner by calling transferOwnership, since onlyOwner
        // is msg.sender. This is admissible: the test contract becomes owner.
        c.transferOwnership(address(this));

        // Give c some initial foreign-token balance so balanceOf returns a nonzero amount.
        vm.deal(address(c), tokenBal);
        ft.setBalance(address(c), tokenBal);

        // Drive the external entry point. P returns true on a successful foreign transfer;
        // M inverts it and returns false.
        bool success = c.withdrawForeignTokens(address(ft));

        // The reference must report success when the foreign token transfer succeeds.
        // The buggy version inverts the result and reports false.
        assertTrue(success);
    }
}

contract SuccessfulForeignToken {
    mapping(address => uint256) public balanceOf;
    bool public shouldFail;

    function setBalance(address who, uint256 amount) external {
        balanceOf[who] = amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        if (shouldFail) return false;
        if (balanceOf[msg.sender] < amount) return false;
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
